// Cleans each newsletter email into plain text for Gemini

const results = [];

for (const item of $input.all()) {
  const email = item.json;

  // 1. Who sent it (just the name, e.g. "TLDR AI")
  let from = '';
  if (email.from && typeof email.from === 'object') {
    from = (email.from.value && email.from.value[0] && email.from.value[0].name) || email.from.text || '';
  } else {
    from = email.from || '';
  }

  // 2. Turn the HTML into readable text
  const html = email.html || email.textAsHtml || '';
  let content = '';

  if (html) {
    content = html
      // remove hidden parts: page head, styles, scripts
      .replace(/<(head|style|script)[\s\S]*?<\/\1>/gi, ' ')
      // keep useful links as "link text (url)", drop junk links
      .replace(/<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi, (match, url, inner) => {
        const text = inner.replace(/<[^>]+>/g, '').trim();
        const junk = /unsubscribe|preferences|view (it )?in (your )?browser|privacy|terms|advertise|mailto:/i;
        if (!text || junk.test(url) || junk.test(text) || !/^https?:/i.test(url)) return text;
        return text + ' (' + url + ')';
      })
      // line breaks where paragraphs and rows end
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|tr|li|h[1-6])>/gi, '\n')
      // remove all remaining tags
      .replace(/<[^>]+>/g, ' ');
  } else {
    content = email.text || '';
  }

  // 3. Fix special characters and tidy up spacing
  content = content
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n)))
    .replace(/&[a-z]+;/gi, ' ')
    .replace(/[\u200B-\u200D\uFEFF\u034F\u00AD]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n\n')
    .trim();

  // 4. Keep it a sensible length for Gemini
  if (content.length > 12000) {
    content = content.slice(0, 12000) + '\n[...cut for length]';
  }

  results.push({
    json: {
      subject: email.subject || '(no subject)',
      from: from,
      date: email.date || '',
      content: content,
    },
  });
}

return results;
